describe('BaseRenderer', () => {
  let renderer;
  let proton;

  beforeEach(() => {
    renderer = new BaseRenderer(document.createElement('div'), '#000');
    proton = new Proton();
    renderer.init(proton);
  });

  it('should add event listeners to proton', () => {
    const eventTypes = [
      'PROTON_UPDATE',
      'PROTON_UPDATE_AFTER',
      'EMITTER_ADDED',
      'EMITTER_REMOVED',
      'PARTICLE_CREATED',
      'PARTICLE_UPDATE',
      'PARTICLE_DEAD'
    ];

    eventTypes.forEach(eventType => {
      expect(proton.addEventListener).toHaveBeenCalledWith(eventType, expect.anything());
    });
  });

  it('should set parent of proton to instance of BaseRenderer', () => {
    expect(proton.parent).toBe(renderer);
  });
});

